class OrderService {
  // Violates SRP + DIP + OCP in 20 lines. Typical LLD starting point.
  public void checkout(Order order, String type) {
    double total = order.getAmount();
    if (type.equals("STUDENT")) total *= 0.9;        // OCP: edit me per coupon
    else if (type.equals("FESTIVAL")) total *= 0.8;

    PostgresOrderRepo repo = new PostgresOrderRepo(); // DIP: concrete inside policy
    repo.save(order);                                 // untestable without DB
    SmtpMailer mailer = new SmtpMailer();             // SRP: pricing + persistence + notify
    mailer.send(order.getEmail(), "paid " + total);
  }
}
// LSP smell elsewhere: class ReadOnlyOrder extends Order { write() { throw ... } }

interface DiscountPolicy { double apply(Order o); }
interface OrderRepository { void save(Order o); }
interface Notifier { void send(String to, String msg); }

class OrderService {
  private final List<DiscountPolicy> policies; // OCP: new discount = new class
  private final OrderRepository repo;          // DIP: owned by domain, injected
  private final Notifier notifier;             // SRP: persistence + notify moved out

  OrderService(List<DiscountPolicy> policies, OrderRepository repo, Notifier notifier) {
    this.policies = policies; this.repo = repo; this.notifier = notifier;
  }
  public void checkout(Order order) {
    double total = order.getAmount();
    for (DiscountPolicy p : policies) total = p.apply(order);
    repo.save(order);
    notifier.send(order.getEmail(), "paid " + total);
  }
}
// ISP: Notifier is 1 method, not a 20-method MessagingService.
// LSP: every DiscountPolicy must honor apply() with no new exceptions.
